Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net: airoha: fix BQL imbalance in TX path

Fix a possible BQL imbalance in airoha_dev_xmit(), where inflight
packets are accounted only for the AIROHA_NUM_TX_RING netdev TX
queues. The queue index is computed as:

    qid = skb_get_queue_mapping(skb) % ARRAY_SIZE(qdma->q_tx)
    txq = netdev_get_tx_queue(dev, qid);

However, airoha_qdma_tx_napi_poll() accounts completions across all
netdev TX queues (num_tx_queues), leading to inconsistent BQL
accounting.

Also reset all netdev TX queues in the ndo_stop callback.

Fixes: 1d304174106c ("net: airoha: Implement BQL support")
Fixes: c9f947769b77 ("net: airoha: Reset BQL stopping the netdevice")
Signed-off-by: Lorenzo Bianconi <lorenzo@kernel.org>
Link: https://patch.msgid.link/20260421-airoha-fix-bql-v1-1-f135afe4275b@kernel.org
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is caused by a mismatch in BQL accounting between the transmit and completion paths. In `airoha_dev_xmit()`, the queue index is computed as `qid = skb_get_queue_mapping(skb) % ARRAY_SIZE(qdma->q_tx)`, which clips to the number of hardware TX rings (AIROHA_NUM_TX_RING). However, the BQL `netdev_tx_sent_queue` call uses this clipped `qid`. In the completion path (`airoha_qdma_tx_napi_poll`), completions are accounted using `skb_get_queue_mapping(skb)` directly (without modulo), which can map to any netdev TX queue (up to `num_tx_queues`). This leads to BQL send/complete imbalance because the same skb can be accounted on different queues in the two paths. Additionally, the `ndo_stop` callback only resets BQL for the first `ARRAY_SIZE(qdma->q_tx)` queues, leaving other TX queues with stale state. The fix aligns both paths to use the same queue determination via `skb_get_tx_queue()` and resets all TX queues on stop.

Here is the patch:

 static int airoha_qdma_tx_napi_poll(struct napi_struct *napi, int budget)
 {
 	struct airoha_tx_irq_queue *irq_q;
 	int id, done = 0, irq_queued;
 	struct airoha_qdma *qdma;
 	struct airoha_eth *eth;
 	u32 status, head;

 	irq_q = container_of(napi, struct airoha_tx_irq_queue, napi);
 	qdma = irq_q->qdma;
 	id = irq_q - &qdma->q_tx_irq[0];
 	eth = qdma->eth;

 	status = airoha_qdma_rr(qdma, REG_IRQ_STATUS(id));
 	head = FIELD_GET(IRQ_HEAD_IDX_MASK, status);
 	head = head % irq_q->size;
 	irq_queued = FIELD_GET(IRQ_ENTRY_LEN_MASK, status);

 	while (irq_queued > 0 && done < budget) {
 		u32 qid, val = irq_q->q[head];
 		struct airoha_qdma_desc *desc;
 		struct airoha_queue_entry *e;
 		struct airoha_queue *q;
 		u32 index, desc_ctrl;
 		struct sk_buff *skb;

 		if (val == 0xff)
 			break;

 		irq_q->q[head] = 0xff; /* mark as done */
 		head = (head + 1) % irq_q->size;
 		irq_queued--;
 		done++;

 		qid = FIELD_GET(IRQ_RING_IDX_MASK, val);
 		if (qid >= ARRAY_SIZE(qdma->q_tx))
 			continue;

 		q = &qdma->q_tx[qid];
 		if (!q->ndesc)
 			continue;

 		index = FIELD_GET(IRQ_DESC_IDX_MASK, val);
 		if (index >= q->ndesc)
 			continue;

 		spin_lock_bh(&q->lock);

 		if (!q->queued)
 			goto unlock;

 		desc = &q->desc[index];
 		desc_ctrl = le32_to_cpu(desc->ctrl);

 		if (!(desc_ctrl & QDMA_DESC_DONE_MASK) &&
 		    !(desc_ctrl & QDMA_DESC_DROP_MASK))
 			goto unlock;

 		e = &q->entry[index];
 		skb = e->skb;

 		dma_unmap_single(eth->dev, e->dma_addr, e->dma_len,
 				 DMA_TO_DEVICE);
 		e->dma_addr = 0;
 		list_add_tail(&e->list, &q->tx_list);

 		WRITE_ONCE(desc->msg0, 0);
 		WRITE_ONCE(desc->msg1, 0);
 		q->queued--;

 		if (skb) {
-			u16 queue = skb_get_queue_mapping(skb);
 			struct netdev_queue *txq;

-			txq = netdev_get_tx_queue(skb->dev, queue);
+			txq = skb_get_tx_queue(skb->dev, skb);
 			netdev_tx_completed_queue(txq, 1, skb->len);
 			dev_kfree_skb_any(skb);
 		}

 		if (q->txq_stopped && q->ndesc - q->queued >= q->free_thr) {
 			/* Since multiple net_device TX queues can share the
 			 * same hw QDMA TX queue, there is no guarantee we have
 			 * inflight packets queued in hw belonging to a
 			 * net_device TX queue stopped in the xmit path.
 			 * In order to avoid any potential net_device TX queue
 			 * stall, we need to wake all the net_device TX queues
 			 * feeding the same hw QDMA TX queue.
 			 */
 			airoha_qdma_wake_netdev_txqs(q);
 		}

 unlock:
 		spin_unlock_bh(&q->lock);
 	}

 	if (done) {
 		int i, len = done >> 7;

 		for (i = 0; i < len; i++)
 			airoha_qdma_rmw(qdma, REG_IRQ_CLEAR_LEN(id),
 					IRQ_CLEAR_LEN_MASK, 0x80);
 		airoha_qdma_rmw(qdma, REG_IRQ_CLEAR_LEN(id),
 				IRQ_CLEAR_LEN_MASK, (done & 0x7f));
 	}

 	if (done < budget && napi_complete(napi))
 		airoha_qdma_irq_enable(&qdma->irq_banks[0], QDMA_INT_REG_IDX0,
 				       TX_DONE_INT_MASK(id));

 	return done;
 }


 static int airoha_dev_stop(struct net_device *dev)
 {
 	struct airoha_gdm_port *port = netdev_priv(dev);
 	struct airoha_qdma *qdma = port->qdma;
 	int i, err;

 	netif_tx_disable(dev);
 	err = airoha_set_vip_for_gdm_port(port, false);
 	if (err)
 		return err;

-	for (i = 0; i < ARRAY_SIZE(qdma->q_tx); i++)
+	for (i = 0; i < dev->num_tx_queues; i++)
 		netdev_tx_reset_subqueue(dev, i);

 	airoha_set_gdm_port_fwd_cfg(qdma->eth, REG_GDM_FWD_CFG(port->id),
 				    FE_PSE_PORT_DROP);

 	if (atomic_dec_and_test(&qdma->users)) {
 		airoha_qdma_clear(qdma, REG_QDMA_GLOBAL_CFG,
 				  GLOBAL_CFG_TX_DMA_EN_MASK |
 				  GLOBAL_CFG_RX_DMA_EN_MASK);

 		for (i = 0; i < ARRAY_SIZE(qdma->q_tx); i++) {
 			if (!qdma->q_tx[i].ndesc)
 				continue;

 			airoha_qdma_cleanup_tx_queue(&qdma->q_tx[i]);
 		}
 	}

 	return 0;
 }


 static netdev_tx_t airoha_dev_xmit(struct sk_buff *skb,
 				   struct net_device *dev)
 {
 	struct airoha_gdm_port *port = netdev_priv(dev);
 	struct airoha_qdma *qdma = port->qdma;
 	u32 nr_frags, tag, msg0, msg1, len;
 	struct airoha_queue_entry *e;
 	struct netdev_queue *txq;
 	struct airoha_queue *q;
 	LIST_HEAD(tx_list);
 	void *data;
 	int i, qid;
 	u16 index;
 	u8 fport;

 	qid = skb_get_queue_mapping(skb) % ARRAY_SIZE(qdma->q_tx);
 	tag = airoha_get_dsa_tag(skb, dev);

 	msg0 = FIELD_PREP(QDMA_ETH_TXMSG_CHAN_MASK,
 			  qid / AIROHA_NUM_QOS_QUEUES) |
 	       FIELD_PREP(QDMA_ETH_TXMSG_QUEUE_MASK,
 			  qid % AIROHA_NUM_QOS_QUEUES) |
 	       FIELD_PREP(QDMA_ETH_TXMSG_SP_TAG_MASK, tag);
 	if (skb->ip_summed == CHECKSUM_PARTIAL)
 		msg0 |= FIELD_PREP(QDMA_ETH_TXMSG_TCO_MASK, 1) |
 			FIELD_PREP(QDMA_ETH_TXMSG_UCO_MASK, 1) |
 			FIELD_PREP(QDMA_ETH_TXMSG_ICO_MASK, 1);

 	/* TSO: fill MSS info in tcp checksum field */
 	if (skb_is_gso(skb)) {
 		if (skb_cow_head(skb, 0))
 			goto error;

 		if (skb_shinfo(skb)->gso_type & (SKB_GSO_TCPV4 |
 						 SKB_GSO_TCPV6)) {
 			__be16 csum = cpu_to_be16(skb_shinfo(skb)->gso_size);

 			tcp_hdr(skb)->check = (__force __sum16)csum;
 			msg0 |= FIELD_PREP(QDMA_ETH_TXMSG_TSO_MASK, 1);
 		}
 	}

 	fport = airoha_get_fe_port(port);
 	msg1 = FIELD_PREP(QDMA_ETH_TXMSG_FPORT_MASK, fport) |
 	       FIELD_PREP(QDMA_ETH_TXMSG_METER_MASK, 0x7f);

 	q = &qdma->q_tx[qid];
 	if (WARN_ON_ONCE(!q->ndesc))
 		goto error;

 	spin_lock_bh(&q->lock);

-	txq = netdev_get_tx_queue(dev, qid);
+	txq = skb_get_tx_queue(dev, skb);
 	nr_frags = 1 + skb_shinfo(skb)->nr_frags;

 	if (q->queued + nr_frags >= q->ndesc) {
 		/* not enough space in the queue */
 		netif_tx_stop_queue(txq);
 		q->txq_stopped = true;
 		spin_unlock_bh(&q->lock);
 		return NETDEV_TX_BUSY;
 	}

 	len = skb_headlen(skb);
 	data = skb->data;

 	e = list_first_entry(&q->tx_list, struct airoha_queue_entry,
 			     list);
 	index = e - q->entry;

 	for (i = 0; i < nr_frags; i++) {
 		struct airoha_qdma_desc *desc = &q->desc[index];
 		skb_frag_t *frag = &skb_shinfo(skb)->frags[i];
 		dma_addr_t addr;
 		u32 val;

 		addr = dma_map_single(dev->dev.parent, data, len,
 				      DMA_TO_DEVICE);
 		if (unlikely(dma_mapping_error(dev->dev.parent, addr)))
 			goto error_unmap;

 		list_move_tail(&e->list, &tx_list);
 		e->skb = i ? NULL : skb;
 		e->dma_addr = addr;
 		e->dma_len = len;

 		e = list_first_entry(&q->tx_list, struct airoha_queue_entry,
 				     list);
 		index = e - q->entry;

 		val = FIELD_PREP(QDMA_DESC_LEN_MASK, len);
 		if (i < nr_frags - 1)
 			val |= FIELD_PREP(QDMA_DESC_MORE_MASK, 1);
 		WRITE_ONCE(desc->ctrl, cpu_to_le32(val));
 		WRITE_ONCE(desc->addr, cpu_to_le32(addr));
 		val = FIELD_PREP(QDMA_DESC_NEXT_ID_MASK, index);
 		WRITE_ONCE(desc->data, cpu_to_le32(val));
 		WRITE_ONCE(desc->msg0, cpu_to_le32(msg0));
 		WRITE_ONCE(desc->msg1, cpu_to_le32(msg1));
 		WRITE_ONCE(desc->msg2, cpu_to_le32(0xffff));

 		data = skb_frag_address(frag);
 		len = skb_frag_size(frag);
 	}
 	q->queued += i;

 	skb_tx_timestamp(skb);
 	netdev_tx_sent_queue(txq, skb->len);

 	if (netif_xmit_stopped(txq) || !netdev_xmit_more())
 		airoha_qdma_rmw(qdma, REG_TX_CPU_IDX(qid),
 				TX_RING_CPU_IDX_MASK,
 				FIELD_PREP(TX_RING_CPU_IDX_MASK, index));

 	if (q->ndesc - q->queued < q->free_thr) {
 		netif_tx_stop_queue(txq);
 		q->txq_stopped = true;
 	}

 	spin_unlock_bh(&q->lock);

 	return NETDEV_TX_OK;

 error_unmap:
 	while (!list_empty(&tx_list)) {
 		e = list_first_entry(&tx_list, struct airoha_queue_entry,
 				     list);
 		dma_unmap_single(dev->dev.parent, e->dma_addr, e->dma_len,
 				 DMA_TO_DEVICE);
 		e->dma_addr = 0;
 		list_move_tail(&e->list, &q->tx_list);
 	}

 	spin_unlock_bh(&q->lock);
 error:
 	dev_kfree_skb_any(skb);
 	dev->stats.tx_dropped++;

 	return NETDEV_TX_OK;
 }



